    $this->query->addOrderBy($this->tableAlias, $this->realField, $this->options['order'], NULL, $params);
  }

  /**
   * {@inheritdoc}
   */
  public function adminLabel($short = FALSE) {
    return $this->getField(parent::adminLabel($short));
  }

}

